actions.script:
const out = ec.service.sync().name('ironstone.commons.ScheduleServices.get#Resources').parameters({resourceType: type || 'all', text: text || null,
    minCapacity: Number(minCapacity) > 0 ? Math.floor(Number(minCapacity)) : null}).call()
const defaults = ec.service.sync().name('ironstone.commons.CalendarServices.get#CalendarDefaults').call()?.defaults || {}
// "Scheduling admin": Maintenance's Scheduling for a user who opens it (impl-maintenance P16; its menu's permissions)
let adminUrl = null
try {
    const caps = ec.resource.script('component://mr-boss/service/ironstone/maintenance/Maintenance.js').execute('capabilities', {}).capabilities || {}
    if (caps.read && (caps.policyView || caps.policyEdit || caps.bookingViewAssigned || caps.supervise || caps.resourceView))
        adminUrl = '/qapps/Maintenance/Scheduling/Resources'
} catch (err) { ec.logger.warn(`Scheduling admin link for ${ec.user.username} not read: ${err && err.message ? err.message : err}`) }
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {resourceList: out.resourceList, timeZone: ec.user.timeZone,
    todayText: ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd'), workStart: defaults.workStart, workEnd: defaults.workEnd,
    weekStart: defaults.weekStart, adminUrl: adminUrl})

// a resource as type and id, or as its key (room|id); the time as start and end, or a day with from and to
const key = String(resource || '')
const at = key.indexOf('|')
const day = date ? String(date).substring(0, 10) : ''
const out = ec.service.sync().name('ironstone.commons.ScheduleServices.book#ResourceSlot').parameters({resourceType: resourceType || (at > 0 ? key.substring(0, at) : ''),
    resourceId: resourceId || (at > 0 ? key.substring(at + 1) : ''), start: start || (day ? day + ' ' + (from || '09:00') : ''),
    end: end || (day ? day + ' ' + (to || '10:00') : ''), purpose: purpose || null, notes: notes || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {workEffortId: out.workEffortId, statusId: out.statusId, requiresApproval: out.requiresApproval,
    messageInfos: [{type: out.requiresApproval ? 'warning' : 'success', message: out.message,
        link: '/qapps/Commons/Calendar/EventDetail?workEffortId=' + out.workEffortId, linkText: ec.l10n.localize('Open')}]})

const out = ec.service.sync().name('ironstone.commons.ScheduleServices.cancel#MyBooking').parameters({workEffortId: workEffortId || '',
    resourceType: resourceType || '', resourceId: resourceId || ''}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {eventCancelled: out.eventCancelled, messageInfos: [{type: 'success', message: out.message}]})
